<?php
require_once __DIR__ . '/_layout.php'; requirePermission('inspections.manage');
$requiredPhotos=['front','rear','left','right','interior','dashboard'];
if(requestMethod()==='POST'){
    requireCsrfPost();$action=$_POST['action']??'';
    try{
        if($action==='create'){
            foreach($requiredPhotos as $photoType){if(!isset($_FILES['photos']['error'][$photoType])||$_FILES['photos']['error'][$photoType]!==UPLOAD_ERR_OK)throw new InvalidArgumentException('All six required inspection photos must be provided.');}
            $id=withTransaction(function()use($requiredPhotos){$id=createInspection(['contract_id'=>(int)($_POST['contract_id']??0),'inspection_type'=>$_POST['inspection_type']??'','inspected_at'=>$_POST['inspected_at']??'','mileage'=>$_POST['mileage']??0,'fuel_level'=>$_POST['fuel_level']??0,'cleanliness'=>$_POST['cleanliness']??'','accessories'=>$_POST['accessories']??'','notes'=>$_POST['notes']??'','customer_signature_status'=>$_POST['customer_signature_status']??'pending']);foreach($requiredPhotos as $photoType){$file=['name'=>$_FILES['photos']['name'][$photoType],'type'=>$_FILES['photos']['type'][$photoType],'tmp_name'=>$_FILES['photos']['tmp_name'][$photoType],'error'=>$_FILES['photos']['error'][$photoType],'size'=>$_FILES['photos']['size'][$photoType]];$stored=storeValidatedImage($file,'inspections');dbExecute('INSERT INTO inspection_photos(inspection_id,photo_type,storage_path,mime_type,file_size,captured_at,created_by)VALUES(:inspection,:type,:path,:mime,:size,NOW(),:user)',['inspection'=>$id,'type'=>$photoType,'path'=>$stored['path'],'mime'=>$stored['mime_type'],'size'=>$stored['size'],'user'=>currentUserId()]);}return$id;});flash('success','Inspection validated with required photos: #'.$id);
        }elseif($action==='damage'){
            $inspection=dbFetchOne('SELECT vi.*,r.agency_id FROM vehicle_inspections vi JOIN rental_contracts rc ON rc.id=vi.contract_id JOIN reservations r ON r.id=rc.reservation_id WHERE vi.id=:id',['id'=>(int)($_POST['inspection_id']??0)]);if(!$inspection)throw new InvalidArgumentException('Inspection not found.');requireAgencyAccess($inspection['agency_id']);$estimated=positiveMoney($_POST['estimated_cost']??'0')??'0.00';dbExecute('INSERT INTO vehicle_damages(inspection_id,vehicle_id,zone,damage_type,description,severity,estimated_cost,responsible_party,payment_status,status,created_by)VALUES(:inspection,:vehicle,:zone,:type,:description,:severity,:cost,:party,\'pending\',\'open\',:user)',['inspection'=>$inspection['id'],'vehicle'=>$inspection['vehicle_id'],'zone'=>trim((string)$_POST['zone']),'type'=>trim((string)$_POST['damage_type']),'description'=>trim((string)$_POST['description']),'severity'=>validateChoice($_POST['severity']??'',['minor','moderate','major'],'minor'),'cost'=>$estimated,'party'=>validateChoice($_POST['responsible_party']??'',['customer','agency','third_party','unknown'],'unknown'),'user'=>currentUserId()]);$id=(int)db()->lastInsertId();dbExecute("UPDATE vehicles SET status='damaged',updated_by=:user WHERE id=:vehicle",['user'=>currentUserId(),'vehicle'=>$inspection['vehicle_id']]);auditLog('damage.recorded','vehicle_damage',$id,null,['estimated_cost'=>$estimated],$inspection['agency_id']);flash('success','Damage recorded and vehicle marked damaged.');
        }
    }catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Inspection operation failed');flash('danger','The inspection operation could not be completed.');}safeRedirect('inspections.php');
}
$agencyIds=currentAgencyIds();if(!$agencyIds)$agencyIds=[0];$ph=implode(',',array_fill(0,count($agencyIds),'?'));$contracts=dbFetchAll("SELECT rc.id,rc.contract_number,rc.status,r.reference,c.first_name,c.last_name,v.registration_number FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN customers c ON c.id=r.customer_id JOIN vehicles v ON v.id=r.vehicle_id WHERE r.agency_id IN ($ph) AND rc.status IN ('generated','signed','active','amended') ORDER BY rc.created_at DESC",$agencyIds);$inspections=dbFetchAll("SELECT vi.*,rc.contract_number,v.registration_number,c.first_name,c.last_name,(SELECT COUNT(*) FROM inspection_photos ip WHERE ip.inspection_id=vi.id) photo_count FROM vehicle_inspections vi JOIN rental_contracts rc ON rc.id=vi.contract_id JOIN reservations r ON r.id=rc.reservation_id JOIN vehicles v ON v.id=vi.vehicle_id JOIN customers c ON c.id=vi.customer_id WHERE r.agency_id IN ($ph) ORDER BY vi.inspected_at DESC LIMIT 100",$agencyIds);$comparisons=dbFetchAll("SELECT rc.contract_number,v.registration_number,co.mileage checkout_mileage,rt.mileage return_mileage,co.fuel_level checkout_fuel,rt.fuel_level return_fuel,TIMESTAMPDIFF(MINUTE,r.return_at,rt.inspected_at) late_minutes FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN vehicles v ON v.id=r.vehicle_id JOIN vehicle_inspections co ON co.contract_id=rc.id AND co.inspection_type='checkout' JOIN vehicle_inspections rt ON rt.contract_id=rc.id AND rt.inspection_type='return' WHERE r.agency_id IN ($ph) ORDER BY rt.inspected_at DESC",$agencyIds);
backofficeHeader('Inspections','inspections.php');?><?php pageHeader('Checkout and return inspections', 'Capture immutable vehicle condition, photos, mileage, fuel, and damage.', ['breadcrumbs'=>[['label'=>'Rentals'],['label'=>'Inspections']],'primary'=>['label'=>'Add inspection','href'=>'#new-inspection']]); ?><div class="grid"><section class="card" id="new-inspection"><h2>Validate inspection</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="create"><label>Contract<select name="contract_id"><?php foreach($contracts as $c):?><option value="<?=e($c['id'])?>"><?=e($c['contract_number'].' — '.$c['registration_number'].' — '.$c['first_name'].' '.$c['last_name'])?></option><?php endforeach;?></select></label><label>Type<select name="inspection_type"><option>checkout</option><option>return</option></select></label><label>Date/time<input type="datetime-local" name="inspected_at" value="<?=e(date('Y-m-d\TH:i'))?>" required></label><label>Mileage<input type="number" name="mileage" min="0" required></label><label>Fuel level %<input type="number" name="fuel_level" min="0" max="100" step="0.1" required></label><label>Cleanliness<select name="cleanliness"><option>clean</option><option>acceptable</option><option>dirty</option></select></label><label>Accessories (comma separated)<input name="accessories"></label><label>Customer signature<select name="customer_signature_status"><option>pending</option><option>signed</option><option>refused</option></select></label><label>Notes<textarea name="notes"></textarea></label><div class="grid"><?php foreach($requiredPhotos as $photo):?><label><?=e(ucfirst($photo))?> photo<input type="file" name="photos[<?=e($photo)?>]" accept="image/jpeg,image/png,image/webp" required></label><?php endforeach;?></div><button class="btn primary">Validate immutable inspection</button></form></section><section class="card"><h2>Inspection history</h2><div class="table-wrap"><table><tr><th>Contract</th><th>Vehicle</th><th>Type</th><th>Mileage</th><th>Fuel</th><th>Photos</th><th>Damage</th></tr><?php foreach($inspections as $i):?><tr><td><?=e($i['contract_number'])?></td><td><?=e($i['registration_number'])?></td><td><?=statusBadge($i['inspection_type'])?></td><td><?=e($i['mileage'])?></td><td><?=e($i['fuel_level'])?>%</td><td><?=e($i['photo_count'])?>/6</td><td><form method="post"><?=csrfField()?><input type="hidden" name="action" value="damage"><input type="hidden" name="inspection_id" value="<?=e($i['id'])?>"><input name="zone" placeholder="Zone" required><input name="damage_type" placeholder="Damage type" required><input name="description" placeholder="Description" required><select name="severity"><option>minor</option><option>moderate</option><option>major</option></select><input name="estimated_cost" placeholder="Estimated cost"><select name="responsible_party"><option>customer</option><option>agency</option><option>third_party</option><option>unknown</option></select><button class="btn danger">Record damage</button></form></td></tr><?php endforeach;?></table></div></section></div><section class="card" style="margin-top:1rem"><h2>Checkout / return comparison</h2><div class="table-wrap"><table><tr><th>Contract</th><th>Vehicle</th><th>Mileage difference</th><th>Fuel difference</th><th>Late minutes</th></tr><?php foreach($comparisons as $c):?><tr><td><?=e($c['contract_number'])?></td><td><?=e($c['registration_number'])?></td><td><?=e($c['return_mileage']-$c['checkout_mileage'])?> km</td><td><?=e($c['return_fuel']-$c['checkout_fuel'])?>%</td><td><?=e(max(0,(int)$c['late_minutes']))?></td></tr><?php endforeach;?></table></div></section><?php backofficeFooter();
